import os
from typing import Dict, Any, Optional
from google.cloud import documentai
from google.cloud.documentai_v1 import types

def extract_expense_fields(
    file_path: str,
    project_id: str,
    location: str,
    processor_id: str
) -> Dict[str, Any]:
    """
    Extract expense fields from a document using Google Document AI Invoice Parser.
    Returns normalized JSON with standard expense fields.
    """
    client = documentai.DocumentProcessorServiceClient()
    processor_name = client.processor_path(project_id, location, processor_id)

    with open(file_path, "rb") as f:
        file_content = f.read()

    raw_document = types.RawDocument(content=file_content, mime_type="application/pdf")
    request = types.ProcessRequest(name=processor_name, raw_document=raw_document)
    result = client.process_document(request=request)

    document = result.document
    entities = document.entities

    normalized = {
        "vendor_name": None,
        "invoice_date": None,
        "invoice_number": None,
        "total_amount": None,
        "tax_amount": None,
        "currency": None,
        "line_items": []
    }

    for entity in entities:
        entity_type = entity.type_
        normalized_value = entity.normalized_value.text if entity.normalized_value else entity.mention_text

        if entity_type == "supplier_name":
            normalized["vendor_name"] = normalized_value
        elif entity_type == "receiver_name":
            pass
        elif entity_type == "invoice_date":
            normalized["invoice_date"] = normalized_value
        elif entity_type == "invoice_id":
            normalized["invoice_number"] = normalized_value
        elif entity_type == "total_amount":
            normalized["total_amount"] = float(normalized_value) if normalized_value else None
        elif entity_type == "net_amount":
            pass
        elif entity_type == "tax_amount":
            normalized["tax_amount"] = float(normalized_value) if normalized_value else None
        elif entity_type == "currency":
            normalized["currency"] = normalized_value
        elif entity_type == "line_item":
            line_item = {}
            for prop in entity.properties:
                prop_type = prop.type_
                prop_value = prop.normalized_value.text if prop.normalized_value else prop.mention_text
                if prop_type == "line_item/description":
                    line_item["description"] = prop_value
                elif prop_type == "line_item/amount":
                    line_item["amount"] = float(prop_value) if prop_value else None
                elif prop_type == "line_item/quantity":
                    line_item["quantity"] = float(prop_value) if prop_value else None
                elif prop_type == "line_item/unit_price":
                    line_item["unit_price"] = float(prop_value) if prop_value else None
            if line_item:
                normalized["line_items"].append(line_item)

    return normalized
